CREATE OR REPLACE FUNCTION veloce_private.valid_customs_items(items jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
    item JSONB;
    quantity_value NUMERIC;
    unit_value NUMERIC;
    unit_weight NUMERIC;
BEGIN
    IF items IS NULL OR jsonb_typeof(items) <> 'array' THEN
        RETURN FALSE;
    END IF;

    IF jsonb_array_length(items) > 500 THEN
        RETURN FALSE;
    END IF;

    FOR item IN SELECT value FROM jsonb_array_elements(items)
    LOOP
        IF jsonb_typeof(item) <> 'object'
           OR NOT item ?& ARRAY[
               'description', 'quantity', 'unit_value',
               'unit_weight_kg', 'origin_country', 'hs_code'
           ]
        THEN
            RETURN FALSE;
        END IF;

        IF jsonb_typeof(item -> 'description') IS DISTINCT FROM 'string'
           OR length(btrim(item ->> 'description')) NOT BETWEEN 1 AND 500
           OR jsonb_typeof(item -> 'origin_country')
                IS DISTINCT FROM 'string'
           OR (item ->> 'origin_country') !~ '^[A-Z]{2}$'
           OR jsonb_typeof(item -> 'hs_code') IS DISTINCT FROM 'string'
           OR (item ->> 'hs_code') !~ '^([0-9]{6}|[0-9]{8}|[0-9]{10})$'
           OR jsonb_typeof(item -> 'quantity') IS DISTINCT FROM 'number'
           OR jsonb_typeof(item -> 'unit_value') IS DISTINCT FROM 'string'
           OR jsonb_typeof(item -> 'unit_weight_kg')
                IS DISTINCT FROM 'string'
        THEN
            RETURN FALSE;
        END IF;

        -- Decimal strings preserve exact values across JSON clients.
        IF (item ->> 'unit_value') !~ '^[0-9]{1,18}(\.[0-9]{1,2})?$'
           OR (item ->> 'unit_weight_kg')
                !~ '^[0-9]{1,9}(\.[0-9]{1,3})?$'
        THEN
            RETURN FALSE;
        END IF;

        quantity_value := (item ->> 'quantity')::NUMERIC;
        unit_value := (item ->> 'unit_value')::NUMERIC;
        unit_weight := (item ->> 'unit_weight_kg')::NUMERIC;

        IF quantity_value <> trunc(quantity_value)
           OR quantity_value NOT BETWEEN 1 AND 1000000
           OR unit_value < 0
           OR unit_weight <= 0
        THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    RETURN TRUE;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN FALSE;
END;
$function$
